// Mechanical extraction of existing presentation only. Run with --check in CI.
// No application/session state is evaluated and no economic rule is authored.
const fs = require('node:fs');
const path = require('node:path');
const assert = require('node:assert/strict');
const { createHash } = require('node:crypto');
const { freeNames, rendererDeclarations } = require('./banking-detail-syntax.cjs');
const ROOTS = Object.freeze([
  'renderReadyTimesheetGroupedRows', 'renderTimesheetParentRows', 'renderSimplePreviewRows', 'renderComponentRows',
  'renderCaseActionButtons', 'renderCaseCard', 'renderTaxableFinanceCaseRestructureTeaser',
  'buildOverpaymentRecoveryDisplayLines'
]);
const GLOBALS = new Set(['Array', 'Boolean', 'Date', 'Intl', 'JSON', 'Map', 'Math', 'NaN', 'Number',
  'Object', 'Set', 'String', 'WeakSet', 'console', 'undefined']);
const STATIC_DECLARATIONS = new Set(['expenseInternalCodes', 'FINANCE_CLEAR_RESOLUTION_FAMILIES',
  'timesheetExpenseSourceRefRe', 'stickyReadySelectBodyCellStyle']);
const root = path.resolve(__dirname, '../..');
const output = path.join(root, 'js/banking-pay-modal-v2-details-legacy.js');
const digest = source => createHash('sha256').update(source).digest('hex');

function build(source) {
  source = source.replaceAll('\r\n', '\n');
  const declarations = rendererDeclarations(source);
  const functions = new Set();
  const external = new Set();
  function visit(name) {
    if (functions.has(name) || external.has(name) || GLOBALS.has(name)) return;
    const declaration = declarations.get(name);
    if (!declaration?.isFunction && !STATIC_DECLARATIONS.has(name)) { external.add(name); return; }
    assert.ok(declaration, `Missing static detail dependency: ${name}`);
    assert.equal(declaration.statement.declarations.length, 1, `Review shared declaration for ${name}`);
    functions.add(name);
    freeNames(declaration.node).forEach(visit);
  }
  ROOTS.forEach(visit);
  const selected = [...functions].map(name => declarations.get(name)).sort((a, b) => a.statement.start - b.statement.start);
  const inputs = [...external].sort();
  const bodies = selected.map(declaration => declaration.source).join('\n\n');
  const manifest = selected.map(declaration => ({ name: declaration.name, sha256: digest(declaration.source) }));
  const text = `/* Generated by tests/fixtures/generate-banking-detail-renderers.cjs.
 * Existing Banking Pay detail presentation, unchanged complete declarations.
 * This is NOT a new payment, selection or financial authority. The parent
 * controller supplies bounded accepted data and retains all mutation owners.
 * Do not hand-edit generated bodies. Review source parity before regeneration.
 */
(function(root){
  'use strict';
  const REQUIRED_CONTEXT=Object.freeze(${JSON.stringify(inputs)});
  const SOURCE_MANIFEST=Object.freeze(${JSON.stringify(manifest)}.map(Object.freeze));
  function create(context){
    if(!context||typeof context!=='object'||Array.isArray(context))throw new TypeError('Bounded Banking detail context required');
    for(const key of REQUIRED_CONTEXT){
      if(!Object.prototype.hasOwnProperty.call(context,key))throw new TypeError('Missing Banking detail context: '+key);
    }
    const {${inputs.join(',')}}=context;
${bodies}
    return Object.freeze({${ROOTS.join(',')}});
  }
  const api=Object.freeze({create,REQUIRED_CONTEXT,SOURCE_MANIFEST});
  if(typeof module==='object'&&module.exports)module.exports=api;
  else root.CloudTMSBankingPayLegacyDetailsV2=api;
})(typeof window==='object'?window:this);
`;
  return { text, selected, inputs, declarations, sourceHash: digest(source) };
}
if (require.main === module) {
  const result = build(fs.readFileSync(path.join(root, 'js/main.js'), 'utf8'));
  if (process.argv.includes('--check')) assert.equal(fs.readFileSync(output, 'utf8').replaceAll('\r\n', '\n'), result.text,
    'Generated Banking details differ; review the existing renderer and regenerate deliberately');
  else fs.writeFileSync(output, result.text);
  console.log(JSON.stringify({ mode: process.argv.includes('--check') ? 'check' : 'generate',
    complete_declarations: result.selected.length, external_inputs: result.inputs.length, source_sha256: result.sourceHash }));
}
module.exports = { build, ROOTS, GLOBALS };
